package org.slavicmyths.quest185;
import net.minecraft.server.level.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.monster.Enemy;
import net.minecraft.nbt.*;
import net.neoforged.bus.api.*;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.event.entity.living.*;
import net.neoforged.neoforge.event.entity.player.*;
import net.neoforged.neoforge.event.tick.*;
import org.slavicmyths.entity.LandSpiritEntity;
@EventBusSubscriber(modid="slavicmyths")
public final class Quest185Events {
 public static boolean mor(Entity e){return e instanceof LandSpiritEntity s&&s.morState()==2;}
 @SubscribeEvent public static void death(LivingDeathEvent e){if(!(e.getSource().getEntity() instanceof ServerPlayer p))return;var victim=e.getEntity();var n=Quest185Story.data(p);if(mor(victim)&&!victim.getPersistentData().hasUUID("summonedByPolozUUID")&&!((LandSpiritEntity)victim).morClone()){n.putInt("MorKills",Math.min(1000000,n.getInt("MorKills")+1));int kind=((LandSpiritEntity)victim).mor.kind();if(kind>=1&&kind<=4)n.putInt("BasicKills",Math.min(1000000,n.getInt("BasicKills")+1));if(kind==5)n.putBoolean("Likho",true);if(kind==6)n.putBoolean("Ovinnik",true);n.putBoolean("SeenMor",true);if(!n.contains("FirstMorKillAt"))n.putLong("FirstMorKillAt",Quest185Story.now(p));var counts=n.getCompound("MorKillsByType");String key=net.minecraft.core.registries.BuiltInRegistries.ENTITY_TYPE.getKey(victim.getType()).toString();counts.putInt(key,counts.getInt(key)+1);n.put("MorKillsByType",counts);Quest185Story.invite(p);}
  if(victim instanceof Enemy&&!mor(victim)&&net.minecraft.core.registries.BuiltInRegistries.ENTITY_TYPE.getKey(victim.getType()).getNamespace().equals("minecraft")&&Quest185Story.status(p,8)==Quest185State.Status.ACTIVE&&p.serverLevel().getEntitiesOfClass(org.slavicmyths.wolf.GreyWolf.class,p.getBoundingBox().inflate(12),w->!(w instanceof WolfSupport)&&w.distanceToSqr(victim)<=225).size()>0){var q=Quest185State.quest(n,8);q.putInt("TrainingKills",Math.min(3,q.getInt("TrainingKills")+1));}
 }
 @SubscribeEvent public static void login(PlayerEvent.PlayerLoggedInEvent e){if(e.getEntity() instanceof ServerPlayer p){Quest185Story.migrate(p);Quest185Story.invite(p);}}
 @SubscribeEvent public static void logout(PlayerEvent.PlayerLoggedOutEvent e){Quest185Sessions.logout(e.getEntity().getUUID());}
 @SubscribeEvent public static void clone(PlayerEvent.Clone e){if(e.getEntity() instanceof ServerPlayer p){var old=org.slavicmyths.rpg.PathData.data(e.getOriginal());if(old.contains("Quest185"))org.slavicmyths.rpg.PathData.data(p).put("Quest185",old.getCompound("Quest185").copy());if(e.isWasDeath())Quest185Story.data(p).remove("TrackerUntil");}}
 @SubscribeEvent public static void craft(PlayerEvent.ItemCraftedEvent e){if(e.getEntity() instanceof ServerPlayer p&&e.getCrafting().is(org.slavicmyths.poloz.PolozContent.HORN.get()))Quest185Story.data(p).putBoolean("Horn",true);}
 @SubscribeEvent public static void mitigation(LivingDamageEvent.Pre e){if(e.getEntity().hasEffect(Quest185Content.WARD_EFFECT)&&e.getSource().getMsgId().equals("mor_block"))e.setNewDamage(e.getNewDamage()*.5f);}
 @SubscribeEvent public static void fall(LivingFallEvent e){if(e.getEntity().getPersistentData().getInt("Quest185FallGrace")>0)e.setDamageMultiplier(0);}
 @SubscribeEvent public static void tick(PlayerTickEvent.Post e){if(!(e.getEntity() instanceof ServerPlayer p))return;int grace=p.getPersistentData().getInt("Quest185FallGrace");if(grace>0){if(p.onGround())p.getPersistentData().remove("Quest185FallGrace");else p.getPersistentData().putInt("Quest185FallGrace",grace-1);}if(p.tickCount%10!=0)return;Quest185Sessions.tick(p);var n=Quest185Story.data(p);
  if(Quest185Story.status(p,6)==Quest185State.Status.ACTIVE||!n.getBoolean("SeenMor")){var found=p.serverLevel().getEntitiesOfClass(LivingEntity.class,p.getBoundingBox().inflate(16),Quest185Events::mor);if(!found.isEmpty()){n.putBoolean("SeenMor",true);n.putBoolean("TraceMob",true);if(!n.contains("FirstMorEncounterAt"))n.putLong("FirstMorEncounterAt",Quest185Story.now(p));org.slavicmyths.tales.TaleService.promote(p,"slavicmyths:mor_first_signs",2,false);}}
  if(Quest185Story.status(p,6)==Quest185State.Status.ACTIVE&&!n.getBoolean("TraceBlock")){var eye=p.getEyePosition();var ray=p.serverLevel().clip(new net.minecraft.world.level.ClipContext(eye,eye.add(p.getLookAngle().scale(6)),net.minecraft.world.level.ClipContext.Block.COLLIDER,net.minecraft.world.level.ClipContext.Fluid.NONE,p));if(org.slavicmyths.mor.MorBlocks.index(p.level().getBlockState(ray.getBlockPos()))>=0){n.putBoolean("TraceBlock",true);n.putBoolean("InfectionKnown",true);}}
  if(p.tickCount%20==0){var eye=p.getEyePosition();var hit=p.serverLevel().clip(new net.minecraft.world.level.ClipContext(eye,eye.add(p.getLookAngle().scale(6)),net.minecraft.world.level.ClipContext.Block.COLLIDER,net.minecraft.world.level.ClipContext.Fluid.NONE,p));if(hit.getType()==net.minecraft.world.phys.HitResult.Type.BLOCK){long left=CleansedLand.remaining(p.serverLevel(),hit.getBlockPos());if(left>0){var view=new CompoundTag();view.putString("Kind","land_ward");view.putInt("Seconds",(int)((left+19)/20));view.putLong("Pos",hit.getBlockPos().asLong());Quest185Network.send(p,view);}}}
  if(p.hasEffect(Quest185Content.TRACKER_EFFECT)){var list=new ListTag();int count=0;for(var mob:p.serverLevel().getEntitiesOfClass(LivingEntity.class,p.getBoundingBox().inflate(64),m->(mor(m)||m instanceof org.slavicmyths.poloz.GreatPoloz)&&p.distanceToSqr(m)<=4096)){if(count++>=128)break;var row=new CompoundTag();row.putInt("Entity",mob.getId());list.add(row);}var out=new CompoundTag();out.putString("Kind","tracker");out.put("Targets",list);Quest185Network.send(p,out);}
 }
 @SubscribeEvent public static void level(LevelTickEvent.Post e){if(e.getLevel() instanceof ServerLevel w){CleansingTasks.get(w).tick(w);if(w.dimension()==net.minecraft.world.level.Level.OVERWORLD)CleansingLessons.get(w).tick(w);}}
 @SubscribeEvent public static void damaged(LivingDamageEvent.Post e){if(e.getNewDamage()>0&&e.getEntity() instanceof ServerPlayer p)Quest185Sessions.close(p);}
 @SubscribeEvent(priority=EventPriority.LOWEST) public static void broken(net.neoforged.neoforge.event.level.BlockDropsEvent e){Quest185Origins.remove(e.getLevel(),e.getPos());CleansedLand.remove(e.getLevel(),e.getPos());}
 @SubscribeEvent(priority=EventPriority.LOWEST) public static void placed(net.neoforged.neoforge.event.level.BlockEvent.EntityPlaceEvent e){if(e.getLevel() instanceof ServerLevel w&&!e.isCanceled()){Quest185Origins.remove(w,e.getPos());CleansedLand.remove(w,e.getPos());CleansingLessons.changed(w,e.getPos());}}
 @SubscribeEvent public static void added(MobEffectEvent.Added e){if(e.getEntity() instanceof ServerPlayer p&&e.getEffectInstance()!=null){var effect=e.getEffectInstance().getEffect();if(effect.equals(net.minecraft.world.effect.MobEffects.MOVEMENT_SLOWDOWN)||effect.equals(net.minecraft.world.effect.MobEffects.WEAKNESS)||effect.equals(net.minecraft.world.effect.MobEffects.BLINDNESS)){String key="Quest185Ground."+effect.value().getDescriptionId();if(org.slavicmyths.mor.MorBlockExposure.applying(p)){var old=e.getOldEffectInstance();var fresh=e.getEffectInstance();if(p.getPersistentData().getBoolean(key)||old==null||old.getAmplifier()==fresh.getAmplifier()&&old.getDuration()<=fresh.getDuration())p.getPersistentData().putBoolean(key,true);}else p.getPersistentData().remove(key);}}}
 @SubscribeEvent public static void chunk(net.neoforged.neoforge.event.level.ChunkEvent.Load e){if(e.getChunk() instanceof net.minecraft.world.level.chunk.LevelChunk c&&!c.getLevel().isClientSide)CleansedLand.prune(c);}
 private Quest185Events(){}
}
